                <span className={`w-2.5 h-2.5 rounded-full transition-all duration-500 ${activeHeartbeat ? "bg-emerald-400 scale-125" : "bg-emerald-500"}`}></span>
                <span className="text-xs font-semibold text-slate-400">Connected</span>
              </div>
              <button
