"use client";

import React, { useState, useMemo } from 'react';
import { ProposalScene, SceneItem } from '@/components/3d/ProposalScene';
import { CheckCircle2, Circle } from 'lucide-react';

interface ProposalItem {
  barcode: string;
  name: string;
  category: string;
  daily_rate: number;
  quantity: number;
}

interface ProposalClientProps {
  proposalId: string;
  eventName: string;
  clientName: string;
  eventDate: string;
  items: ProposalItem[];
}

export function ProposalClient({ proposalId, eventName, clientName, eventDate, items }: ProposalClientProps) {
  // Track which items the user has selected/kept in the proposal
  const [selectedItems, setSelectedItems] = useState<Set<string>>(
    new Set(items.map(item => item.barcode))
  );

  const toggleItem = (barcode: string) => {
    const next = new Set(selectedItems);
    if (next.has(barcode)) {
      next.delete(barcode);
    } else {
      next.add(barcode);
    }
    setSelectedItems(next);
  };

  // Calculate live total
  const estimatedTotal = useMemo(() => {
    return items
      .filter(item => selectedItems.has(item.barcode))
      .reduce((total, item) => total + (item.daily_rate * item.quantity), 0);
  }, [items, selectedItems]);

  // Map selected items to 3D Scene primitives
  const sceneItems = useMemo<SceneItem[]>(() => {
    const active = items.filter(i => selectedItems.has(i.barcode));

    // Naive auto-layout for primitives based on category
    let speakerX = -2;
    let lightX = -1.5;

    return active.map((item, index) => {
      const isSpeaker = item.category?.toLowerCase().includes('audio') || item.category?.toLowerCase().includes('speaker');
      const isLight = item.category?.toLowerCase().includes('light');

      let position: [number, number, number] = [0, 0, 0];
      let color = '#222222';
      let size: [number, number, number] = [0.5, 0.5, 0.5];

      if (isSpeaker) {
        position = [speakerX, 0.5, -1];
        speakerX += 1.5;
        color = '#1a1a1a';
        size = [0.6, 1.2, 0.5];
      } else if (isLight) {
        position = [lightX, 0.25, -2];
        lightX += 1.0;
        color = '#44aaff';
        size = [0.4, 0.5, 0.4];
      } else {
        position = [(index % 4) - 1.5, 0.25, (Math.floor(index/4)) * 1.5];
      }

      return {
        id: item.barcode,
        name: item.name,
        category: item.category || 'Misc',
        position,
        size,
        color
      };
    });
  }, [items, selectedItems]);

  return (
    <div className="container mx-auto px-4 py-8 mt-20">
      <div className="mb-8 border-b border-gray-800 pb-6">
        <h1 className="text-3xl md:text-5xl font-bold text-white mb-2">Proposal: {eventName}</h1>
        <p className="text-gray-400 text-lg">Prepared for {clientName} • Event Date: {new Date(eventDate).toLocaleDateString()}</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column: 3D Scene & Media */}
        <div className="lg:col-span-2 space-y-8">
          {/* 3D Viewer */}
          <div>
            <h2 className="text-2xl font-semibold text-white mb-4">Interactive 3D Stage Preview</h2>
            <p className="text-gray-400 mb-4 text-sm">Drag to rotate. As you toggle items off in your checklist, the stage will update live to reflect your selection.</p>
            <div className="h-[500px] w-full relative rounded-xl overflow-hidden border border-gray-800">
              <ProposalScene items={sceneItems} />
            </div>
          </div>

          {/* Media Carousel (Placeholder for now) */}
          <div className="bg-gray-900 rounded-xl border border-gray-800 p-6">
            <h3 className="text-xl font-semibold text-white mb-4">Setup Examples</h3>
            <div className="flex gap-4 overflow-x-auto pb-4 snap-x">
              {items.filter(i => selectedItems.has(i.barcode)).map(item => (
                <div key={item.barcode} className="min-w-[250px] h-[150px] bg-gray-800 rounded-lg flex flex-col items-center justify-center snap-center border border-gray-700">
                  <span className="text-gray-500 mb-2">📸 {item.name}</span>
                  <span className="text-xs text-gray-600">(Media Tagging Pending)</span>
                </div>
              ))}
              {selectedItems.size === 0 && (
                <div className="text-gray-500 p-4">No items selected to preview.</div>
              )}
            </div>
          </div>
        </div>

        {/* Right Column: Item Checklist & Quote */}
        <div className="space-y-6">
          <div className="bg-gray-900 rounded-xl border border-gray-800 p-6 shadow-xl sticky top-24">
            <h2 className="text-2xl font-bold text-white mb-6">Equipment & Services</h2>

            <div className="space-y-3 mb-8 max-h-[50vh] overflow-y-auto pr-2 custom-scrollbar">
              {items.map(item => {
                const isSelected = selectedItems.has(item.barcode);
                return (
                  <div 
                    key={item.barcode}
                    onClick={() => toggleItem(item.barcode)}
                    className={`flex items-start justify-between p-3 rounded-lg border cursor-pointer transition-colors ${
                      isSelected ? 'border-blue-500/50 bg-blue-500/10' : 'border-gray-800 bg-gray-950 hover:border-gray-700'
                    }`}
                  >
                    <div className="flex items-start gap-3">
                      <div className="mt-1 flex-shrink-0">
                        {isSelected ? (
                          <CheckCircle2 className="w-5 h-5 text-blue-500" />
                        ) : (
                          <Circle className="w-5 h-5 text-gray-600" />
                        )}
                      </div>
                      <div>
                        <p className={`font-medium ${isSelected ? 'text-white' : 'text-gray-400'}`}>
                          {item.name} {item.quantity > 1 && `(x${item.quantity})`}
                        </p>
                        <p className="text-sm text-gray-500">{item.category}</p>
                      </div>
                    </div>
                    <p className={`font-semibold ${isSelected ? 'text-green-400' : 'text-gray-600'}`}>
                      ${(item.daily_rate * item.quantity).toFixed(2)}
                    </p>
                  </div>
                );
              })}
            </div>

            <div className="border-t border-gray-800 pt-6">
              <div className="flex justify-between items-center mb-6">
                <span className="text-gray-400 text-lg">Estimated Total</span>
                <span className="text-3xl font-bold text-white">${estimatedTotal.toFixed(2)}</span>
              </div>

              <button className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 px-6 rounded-lg transition-all shadow-lg shadow-blue-600/20 text-lg">
                Accept Proposal
              </button>
              <p className="text-center text-xs text-gray-500 mt-4">
                Prices do not include tax or labor unless explicitly stated.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { ChevronLeft, ChevronRight, Play } from "lucide-react";

interface DynamicCarouselProps {
  setup: {
    subs: number;
    tops: number;
    towers: number;
    dj: boolean;
  };
}

// Hardcoded examples mapping setup configurations to actual media paths
const MEDIA_CATALOG = [
  {
    type: "image",
    url: "https://images.unsplash.com/photo-1492684223066-81342ee5ff30?auto=format&fit=crop&q=80&w=800",
    tags: ["large", "band", "4-towers"],
    description: "Full Band + DJ Setup with 4 Lighting Towers"
  },
  {
    type: "image",
    url: "https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?auto=format&fit=crop&q=80&w=800",
    tags: ["medium", "dj"],
    description: "Standard DJ Setup"
  },
  {
    type: "image",
    url: "https://images.unsplash.com/photo-1533174072545-7a4b6ad7a6c3?auto=format&fit=crop&q=80&w=800",
    tags: ["small", "dj", "no-towers"],
    description: "Compact DJ Setup (No Truss Towers)"
  },
  {
    type: "image",
    url: "https://images.unsplash.com/photo-1459749411175-04bf5292ceea?auto=format&fit=crop&q=80&w=800",
    tags: ["large", "band"],
    description: "Live Band Stage Setup"
  }
];

export default function DynamicCarousel({ setup }: DynamicCarouselProps) {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [activeMedia, setActiveMedia] = useState(MEDIA_CATALOG);

  useEffect(() => {
    // Basic logic to filter media based on the user's active configuration
    // This makes the carousel feel magically responsive to their 3D build
    let filtered = MEDIA_CATALOG;

    const totalSpeakers = setup.subs + setup.tops;

    if (totalSpeakers >= 6) {
      filtered = MEDIA_CATALOG.filter(m => m.tags.includes("large"));
    } else if (totalSpeakers >= 3) {
      filtered = MEDIA_CATALOG.filter(m => m.tags.includes("medium") || m.tags.includes("large"));
    } else {
      filtered = MEDIA_CATALOG.filter(m => m.tags.includes("small") || m.tags.includes("medium"));
    }

    if (setup.towers >= 2) {
      filtered = filtered.filter(m => !m.tags.includes("no-towers"));
    }

    if (filtered.length === 0) {
      filtered = MEDIA_CATALOG; // Fallback to all if too specific
    }

    // eslint-disable-next-line react-hooks/set-state-in-effect
    setActiveMedia(filtered);
    setCurrentIndex(0);
  }, [setup]);

  const handleNext = () => setCurrentIndex(prev => (prev + 1) % activeMedia.length);
  const handlePrev = () => setCurrentIndex(prev => (prev - 1 + activeMedia.length) % activeMedia.length);

  const currentItem = activeMedia[currentIndex];

  return (
    <div className="w-full bg-slate-900 rounded-2xl overflow-hidden border border-slate-800 shadow-xl relative aspect-video flex flex-col group">

      {/* Media Viewer */}
      <div className="flex-1 relative">
        <img 
          src={currentItem.url} 
          alt={currentItem.description}
          className="w-full h-full object-cover transition-opacity duration-500"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent" />
      </div>

      {/* Controls overlay */}
      <div className="absolute inset-0 flex items-center justify-between p-4 opacity-0 group-hover:opacity-100 transition-opacity">
        <button onClick={handlePrev} className="bg-black/50 hover:bg-black text-white p-2 rounded-full backdrop-blur transition-all">
          <ChevronLeft className="w-6 h-6" />
        </button>
        <button onClick={handleNext} className="bg-black/50 hover:bg-black text-white p-2 rounded-full backdrop-blur transition-all">
          <ChevronRight className="w-6 h-6" />
        </button>
      </div>

      {/* Description overlay */}
      <div className="absolute bottom-0 left-0 right-0 p-4">
        <h3 className="text-white font-medium">{currentItem.description}</h3>
        <div className="flex gap-2 mt-2">
          {activeMedia.map((_, idx) => (
            <div 
              key={idx} 
              className={`h-1.5 rounded-full transition-all ${idx === currentIndex ? 'w-6 bg-blue-500' : 'w-2 bg-gray-500 cursor-pointer hover:bg-gray-400'}`}
              onClick={() => setCurrentIndex(idx)}
            />
          ))}
        </div>
      </div>

    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Cookie, X } from "lucide-react";

export function CookieConsent() {
  const [showBanner, setShowBanner] = useState(false);

  useEffect(() => {
    // Check if consent has already been given
    const consent = localStorage.getItem("djm-cookie-consent");
    if (!consent) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setShowBanner(true);
    }
  }, []);

  const handleAccept = () => {
    localStorage.setItem("djm-cookie-consent", "accepted");
    setShowBanner(false);
  };

  const handleDecline = () => {
    localStorage.setItem("djm-cookie-consent", "declined");
    setShowBanner(false);
  };

  if (!showBanner) return null;

  return (
    <div 
      role="status"
      aria-live="polite"
      className="fixed bottom-6 right-6 left-6 md:right-8 md:left-auto md:max-w-md z-50 animate-in fade-in slide-in-from-bottom-5 duration-300"
    >
      <div className="bg-white/95 dark:bg-slate-900/95 backdrop-blur border border-gray-150 dark:border-slate-800 rounded-3xl p-6 md:p-8 shadow-xl flex flex-col space-y-4">

        {/* Header */}
        <div className="flex items-start justify-between">
          <div className="flex items-center space-x-3 text-blue-600 dark:text-blue-500">
            <div className="p-2 bg-blue-50 dark:bg-blue-900/30 rounded-xl">
              <Cookie className="w-6 h-6" />
            </div>
            <h3 className="font-bold text-gray-900 dark:text-white text-lg">Cookie Notice</h3>
          </div>
          <button 
            onClick={handleDecline} 
            className="text-gray-400 hover:text-gray-600 dark:hover:text-white transition-colors p-1"
            aria-label="Close Notice"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <p className="text-sm text-gray-600 dark:text-gray-400 leading-relaxed">
          We use functional cookies to remember items in your event proposal cart and maintain system preferences (such as light/dark mode). You can read our{" "}
          <a href="/privacy" className="text-blue-600 dark:text-blue-500 font-semibold hover:underline">
            Privacy Policy
          </a>{" "}
          to learn more.
        </p>

        {/* Buttons */}
        <div className="flex items-center space-x-3 pt-2">
          <button 
            onClick={handleAccept} 
            className="flex-grow bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-4 rounded-xl text-sm transition-all shadow-md shadow-blue-500/10 focus:ring-2 focus:ring-blue-500 focus:outline-none"
          >
            Accept All
          </button>
          <button 
            onClick={handleDecline} 
            className="bg-gray-100 dark:bg-slate-850 hover:bg-gray-200 dark:hover:bg-slate-800 text-gray-700 dark:text-gray-300 font-bold py-3 px-4 rounded-xl text-sm transition-all focus:ring-2 focus:ring-gray-300 focus:outline-none"
          >
            Essential Only
          </button>
        </div>

      </div>
    </div>
  );
}

